 35→      { fret: 0, note: 'B' }, { fret: 1, note: 'C' }, { fret: 3, note: 'D' },
 36→      { fret: 5, note: 'E' }, { fret: 6, note: 'F' }, { fret: 8, note: 'G' },
 37→      { fret: 10, note: 'A' }, { fret: 12, note: 'B' }, { fret: 13, note: 'C' },
 38→      { fret: 15, note: 'D' },
