 84→    for (let s = 1; s <= STRING_COUNT; s++) {
 85→      expect(strings.has(s)).toBe(true);
 86→    }
 87→  });
 88→
 89→  it('should include open string notes (fret 0) for all 6 strings', () => {
 90→    const openNotes = FRET_NOTES.filter((n: FretNote) => n.fret === 0);
 91→    expect(openNotes.length).toBe(6);
 92→    const openStrings = new Set(openNotes.map((n: FretNote) => n.string));
 93→    for (let s = 1; s <= STRING_COUNT; s++) {
 94→      expect(openStrings.has(s)).toBe(true);
 95→    }
 96→  });
 97→
 98→  it('should have correct open string notes in standard tuning', () => {
 99→    const openNotes = FRET_NOTES.filter((n: FretNote) => n.fret === 0);
100→    const openNoteMap = new Map(openNotes.map((n: FretNote) => [n.string, n.note]));
101→
102→    expect(openNoteMap.get(6)).toBe('E'); // Low E
103→    expect(openNoteMap.get(5)).toBe('A');
104→    expect(openNoteMap.get(4)).toBe('D');
105→    expect(openNoteMap.get(3)).toBe('G');
106→    expect(openNoteMap.get(2)).toBe('B');
107→    expect(openNoteMap.get(1)).toBe('E'); // High E
108→  });
109→
110→  it('should have the correct total count of natural notes across all strings', () => {
111→    const expectedTotal = Object.values(expectedNaturalNotes)
112→      .reduce((sum, notes) => sum + notes.length, 0);
113→    expect(FRET_NOTES.length).toBe(expectedTotal);
114→  });
115→
116→  it('should contain exactly the correct natural notes for each string', () => {
117→    for (let s = 1; s <= STRING_COUNT; s++) {
118→      const notesOnString = FRET_NOTES
119→        .filter((n: FretNote) => n.string === s)
120→        .map((n: FretNote) => ({ fret: n.fret, note: n.note }))
121→        .sort((a: { fret: number }, b: { fret: number }) => a.fret - b.fret);
122→
123→      const expected = [...expectedNaturalNotes[s]].sort((a, b) => a.fret - b.fret);
124→
125→      expect(notesOnString).toEqual(expected);
126→    }
127→  });
128→
129→  it('should have no duplicate string/fret combinations', () => {
130→    const keys = FRET_NOTES.map((n: FretNote) => `${n.string}-${n.fret}`);
131→    const uniqueKeys = new Set(keys);
132→    expect(uniqueKeys.size).toBe(keys.length);
133→  });
134→
135→  it('should have distinct x positions for notes on different frets of the same string', () => {
136→    const string1Notes = FRET_NOTES.filter((n: FretNote) => n.string === 1);
137→    const xValues = string1Notes.map((n: FretNote) => n.x);
138→    const uniqueX = new Set(xValues);
139→    expect(uniqueX.size).toBe(xValues.length);
140→  });
141→
142→  it('should have distinct y positions for notes on different strings at the same fret', () => {
143→    const openNotes = FRET_NOTES.filter((n: FretNote) => n.fret === 0);
144→    const yValues = openNotes.map((n: FretNote) => n.y);
145→    const uniqueY = new Set(yValues);
146→    expect(uniqueY.size).toBe(yValues.length);
147→  });
148→
149→  it('should have x positions that increase with fret number', () => {
150→    for (let s = 1; s <= STRING_COUNT; s++) {
151→      const notesOnString = FRET_NOTES
152→        .filter((n: FretNote) => n.string === s)
153→        .sort((a: FretNote, b: FretNote) => a.fret - b.fret);
154→
155→      for (let i = 1; i < notesOnString.length; i++) {
156→        expect(notesOnString[i].x).toBeGreaterThan(notesOnString[i - 1].x);
157→      }
158→    }
159→  });
160→
161→  it('should conform to the FretNote interface shape', () => {
162→    const note: FretNote = FRET_NOTES[0];
163→    expect(typeof note.string).toBe('number');
164→    expect(typeof note.fret).toBe('number');
165→    expect(typeof note.note).toBe('string');
166→    expect(typeof note.x).toBe('number');
167→    expect(typeof note.y).toBe('number');
168→  });
169→});
